1	/**
2	 * SFCC-84 build plan step E2 — asserts only this container's own contract
3	 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given `useEinstein()`'s own
4	 * `isLoading`/`recommendations`, does it render `ZimmRecentlyViewedGrid` (with the right computed
5	 * `title`/`itemCountLabel`/`cards`), this page's own empty state (correctly branched on
6	 * `isRegistered`), or neither — and does the item-count label actually pluralize via real ICU
7	 * `plural` resolution. `selectRecentlyViewedFullHistoryCard`, `resolveOrderableVariant`, and
8	 * `ZimmRecentlyViewedGrid` are all mocked at the smallest surface — their own internals already
9	 * have their own coverage elsewhere (`recentlyViewedFullHistoryCard.test.ts`,
10	 * `zimmRecentlyViewedGrid/index.test.tsx`).
11	 *
12	 * **Rewritten for build plan step E2** — the interim mechanism's own view-history-hook and
13	 * product-fetch-utility mocks are gone (both real modules deleted in build plan step E4; see
14	 * index.tsx's own module docblock, which names them directly). Every test case below now drives
15	 * its scenario entirely through `mockUseEinstein`, matching the exact pattern build plan step E1
16	 * already established (`recommended-products/index.test.tsx`). Product fixtures keep the same
17	 * `RecentlyViewedFullHistoryProduct` shape as before — a hydrated Einstein rec is a strict
18	 * superset of it (see index.tsx's own module docblock) — only the mock supplying them changed.
19	 *
20	 * `useMultiSite` is mocked the same way `footer/index.test.tsx` already does for the same reason:
21	 * the empty state's CTAs use the base SFCC `Link` (`@salesforce/retail-react-app/app/components/
22	 * link`), which calls `useMultiSite().buildUrl` internally to site-prefix `href`. A real
23	 * `MemoryRouter` is still required underneath it (that `Link` renders a real `react-router-dom`
24	 * `Link`), matching `footer/index.test.tsx`'s own `renderContainer` wrapper.
25	 *
26	 * The item-count pluralization tests deliberately do NOT mock `react-intl` — an `IntlProvider`
27	 * with an empty `messages` map (matching `recommended-products/index.test.tsx`'s own
28	 * `<IntlProvider locale="en-AU" messages={{}}>`) falls back to each message's own
29	 * `defaultMessage`, so `formatMessage`'s real ICU `plural` resolution runs for real. Mocking
30	 * `formatMessage` itself would defeat the point of this specific test.
31	 */
32	import React from 'react';
33	import { describe, test, expect, vi, afterEach } from 'vitest';
34	import { render, screen, act } from '@testing-library/react';
35	import { IntlProvider } from 'react-intl';
36	import { MemoryRouter } from 'react-router-dom';
37	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
38	import { useCustomerType, useShopperBasketsMutationHelper } from '@salesforce/commerce-sdk-react';
39	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
40	import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
41	import {
42	  selectRecentlyViewedFullHistoryCard,
43	  resolveOrderableVariant,
44	} from '../../utils/recentlyViewedFullHistoryCard';
45	import type { RecentlyViewedFullHistoryProduct } from '../../utils/recentlyViewedFullHistoryCard';
46	import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
47	import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
48	import RecentlyViewed from '.';
49	
50	// Every card this file's own buildCard() builds is `variation: 'plp'` -- narrows the rendered
51	// `ZimmProductCardProps` union so onAddToBag/selectedSizeChipValue/onSizeChipSelect (all `plp`-only
52	// fields) are accessible, matching product-list/index.tsx's own `ProductListCardProps`
53	// `Extract<ZimmProductCardProps, { variation: 'plp' }>` pattern.
54	const asPlpCard = (card: ZimmProductCardProps) => card as Extract<ZimmProductCardProps, { variation: 'plp' }>;
55	
56	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
57	  default: vi.fn(),
58	}));
59	
