/**
 * SFCC-84 build plan step E2 — asserts only this container's own contract
 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given `useEinstein()`'s own
 * `isLoading`/`recommendations`, does it render `ZimmRecentlyViewedGrid` (with the right computed
 * `title`/`itemCountLabel`/`cards`), this page's own empty state (correctly branched on
 * `isRegistered`), or neither — and does the item-count label actually pluralize via real ICU
 * `plural` resolution. `selectRecentlyViewedFullHistoryCard`, `resolveOrderableVariant`, and
 * `ZimmRecentlyViewedGrid` are all mocked at the smallest surface — their own internals already
 * have their own coverage elsewhere (`recentlyViewedFullHistoryCard.test.ts`,
 * `zimmRecentlyViewedGrid/index.test.tsx`).
 *
 * **Rewritten for build plan step E2** — the interim mechanism's own view-history-hook and
 * product-fetch-utility mocks are gone (both real modules deleted in build plan step E4; see
 * index.tsx's own module docblock, which names them directly). Every test case below now drives
 * its scenario entirely through `mockUseEinstein`, matching the exact pattern build plan step E1
 * already established (`recommended-products/index.test.tsx`). Product fixtures keep the same
 * `RecentlyViewedFullHistoryProduct` shape as before — a hydrated Einstein rec is a strict
 * superset of it (see index.tsx's own module docblock) — only the mock supplying them changed.
 *
 * `useMultiSite` is mocked the same way `footer/index.test.tsx` already does for the same reason:
 * the empty state's CTAs use the base SFCC `Link` (`@salesforce/retail-react-app/app/components/
 * link`), which calls `useMultiSite().buildUrl` internally to site-prefix `href`. A real
 * `MemoryRouter` is still required underneath it (that `Link` renders a real `react-router-dom`
 * `Link`), matching `footer/index.test.tsx`'s own `renderContainer` wrapper.
 *
 * The item-count pluralization tests deliberately do NOT mock `react-intl` — an `IntlProvider`
 * with an empty `messages` map (matching `recommended-products/index.test.tsx`'s own
 * `<IntlProvider locale="en-AU" messages={{}}>`) falls back to each message's own
 * `defaultMessage`, so `formatMessage`'s real ICU `plural` resolution runs for real. Mocking
 * `formatMessage` itself would defeat the point of this specific test.
 */
import React from 'react';
import { describe, test, expect, vi, afterEach } from 'vitest';
import { render, screen, act } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useCustomerType, useShopperBasketsMutationHelper } from '@salesforce/commerce-sdk-react';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
import {
  selectRecentlyViewedFullHistoryCard,
  resolveOrderableVariant,
} from '../../utils/recentlyViewedFullHistoryCard';
import type { RecentlyViewedFullHistoryProduct } from '../../utils/recentlyViewedFullHistoryCard';
import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
import RecentlyViewed from '.';

// Every card this file's own buildCard() builds is `variation: 'plp'` -- narrows the rendered
// `ZimmProductCardProps` union so onAddToBag/selectedSizeChipValue/onSizeChipSelect (all `plp`-only
// fields) are accessible, matching product-list/index.tsx's own `ProductListCardProps`
// `Extract<ZimmProductCardProps, { variation: 'plp' }>` pattern.
const asPlpCard = (card: ZimmProductCardProps) => card as Extract<ZimmProductCardProps, { variation: 'plp' }>;

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useCustomerType: vi.fn(),
  useShopperBasketsMutationHelper: vi.fn(),
}));

// Real use-toast.js ships JSX in a .js-extension file that Vitest's default transform can't parse
// when pulled in transitively — same known gap use-toast.js has everywhere else it's imported in
// this codebase's own tests (see recommended-products/index.test.tsx's identical mock).
vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: () => vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
  default: vi.fn(),
}));

vi.mock('../../utils/recentlyViewedFullHistoryCard', () => ({
  selectRecentlyViewedFullHistoryCard: vi.fn(),
  resolveOrderableVariant: vi.fn(),
}));

// Relative path, matching index.tsx's own import — overrideStyling.md's "Importing an
// already-overridden component" doctrine (irrelevant here in the base-path sense, since this
// organism has no base-SFCC equivalent at all, but the relative specifier must still match
// exactly for the mock to intercept the real import).
vi.mock('../../components/ui-kits/organisms/zimmRecentlyViewedGrid', () => ({
  ZimmRecentlyViewedGrid: vi.fn(() => <div data-testid="zimm-recently-viewed-grid-stub" />),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseCustomerType = vi.mocked(useCustomerType);
const mockUseShopperBasketsMutationHelper = vi.mocked(useShopperBasketsMutationHelper);
const mockUseEinstein = vi.mocked(useEinstein);
const mockSelectRecentlyViewedFullHistoryCard = vi.mocked(selectRecentlyViewedFullHistoryCard);
const mockResolveOrderableVariant = vi.mocked(resolveOrderableVariant);
const mockZimmRecentlyViewedGrid = vi.mocked(ZimmRecentlyViewedGrid);

// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
// same "G1" doctrine recentlyViewedCard.test.ts/recentlyViewedFullHistoryCard.test.ts document.
const mockProducts: RecentlyViewedFullHistoryProduct[] = [
  { id: 'rv-1', name: 'Product One' } as RecentlyViewedFullHistoryProduct,
  { id: 'rv-2', name: 'Product Two' } as RecentlyViewedFullHistoryProduct,
];

/**
 * The exact `useEinstein()` return shape this container reads (`isLoading`,
 * `recommendations.recs`, `getRecommendations`) — matching the pattern
 * `recommended-products/index.test.tsx` (build plan step E1) already established for the same
 * hook. No `as never` cast needed here (unlike the other mocks above): `useEinstein` is a base
 * SFCC hook with no real TypeScript types of its own (covered by `vendor.d.ts`'s wildcard
 * `any`-typed module declaration), so `mockReturnValue` imposes no shape constraint — confirmed
 * against E1's own committed test file, which passes a plain object literal the same way.
 */
const mockEinsteinReturn = (
  isLoading: boolean,
  recs: RecentlyViewedFullHistoryProduct[],
  getRecommendations: (...args: unknown[]) => unknown = vi.fn(),
) => {
  mockUseEinstein.mockReturnValue({ isLoading, recommendations: { recs }, getRecommendations });
};

const renderPage = (
  isRegistered: boolean,
  addItemToNewOrExistingBasket: (...args: never[]) => Promise<unknown> = vi.fn().mockResolvedValue(undefined),
) => {
  mockUseMultiSite.mockReturnValue({ buildUrl: (path: string) => path } as never);
  mockUseCustomerType.mockReturnValue({ isRegistered } as never);
  mockUseShopperBasketsMutationHelper.mockReturnValue({ addItemToNewOrExistingBasket } as never);

  return render(
    <MemoryRouter>
      <IntlProvider locale="en-AU" messages={{}}>
        <RecentlyViewed />
      </IntlProvider>
    </MemoryRouter>,
  );
};

afterEach(() => {
  vi.clearAllMocks();
});

describe('RecentlyViewed — cards render when Einstein has recs', () => {
  test('renders ZimmRecentlyViewedGrid, not the empty state, when recs has items, and fires getRecommendations once on mount', () => {
    const mockGetRecommendations = vi.fn();
    mockEinsteinReturn(false, mockProducts, mockGetRecommendations);
    // rv-2 deliberately maps to `null` (e.g. no usable image/name) — proves this container's own
    // `.filter()` drops it instead of forwarding a null card or crashing.
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) =>
      product?.id === 'rv-2'
        ? null
        : {
            id: product?.id ?? '',
            href: `/product/${product?.id ?? ''}`,
            name: product?.name ?? '',
            headingLevel: 'h3',
            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
            variation: 'plp',
          },
    );

    renderPage(true);

    expect(screen.getByTestId('zimm-recently-viewed-grid-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('recently-viewed-empty')).not.toBeInTheDocument();

    // Build plan step E2: this container fires getRecommendations once on mount, for this one
    // recommender, with no seed products — matches recommended-products/index.tsx's own RV branch
    // (build plan step E1; open question 3: Einstein derives from cookieId/userId, not seed
    // products, for this recommender).
    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED);

    expect(mockZimmRecentlyViewedGrid).toHaveBeenCalledTimes(1);
    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    expect(gridProps.title).toBe('Recently Viewed');
    expect(gridProps.cards).toHaveLength(1);
    expect(gridProps.cards[0]).toMatchObject({ id: 'rv-1', variation: 'plp' });
  });
});

describe('RecentlyViewed — page heading (2026-09-10 fix: this page had no Heading element at all)', () => {
  test('renders a real h1 with the page title, in the populated branch', () => {
    mockEinsteinReturn(false, mockProducts);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(null);

    renderPage(true);

