   });
+
+  test('all-stale-history gate (2026-09-15 fix, CodeRabbit finding, personally verified before treating as valid): renders the empty state, not a blank page, when recs has items but every one fails to map to a card', () => {
+    // The exact bug this closes: with the old `recs.length`-based gate, a shopper with real (if
+    // all-stale) history -- every returned rec now offline/deleted, so
+    // `selectRecentlyViewedFullHistoryCard` returns `null` for every one of them -- saw
+    // `recs.length > 0` (2 items) evaluate true and took the grid branch with `cards={[]}`, which
+    // `ZimmRecentlyViewedGrid` renders as `null` per its own documented contract: a blank page with
+    // no explanation, not this page's own empty state.
+    //
+    // Verified directly, not just asserted (this codebase's prove-don't-assert discipline):
+    // temporarily reverting index.tsx's gate back to `recs.length > 0` /
+    // `!isLoading && recs.length === 0` made this exact test fail -- `recently-viewed-empty` was
+    // absent and `zimm-recently-viewed-grid-stub` was present instead -- and restoring the
+    // `cards.length` gate made it pass again.
+    mockEinsteinReturn(false, mockProducts);
+    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(null);
+
+    renderPage(true);
+
+    expect(screen.getByTestId('recently-viewed-empty')).toBeInTheDocument();
+    expect(screen.queryByTestId('zimm-recently-viewed-grid-stub')).not.toBeInTheDocument();
+    expect(screen.getByText("You haven't viewed anything yet.")).toBeInTheDocument();
+  });
 });

